"use client";

import { useState, type ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./avatar.css";

export type AvatarProps = Omit<ComponentProps<"span">, "children"> & {
  name: string;
  src?: string;
  alt?: string;
  /** Shown as a shape at the corner: filled, half, dash or ring. */
  presence?: "online" | "away" | "busy" | "offline";
};

/** The same name always gets the same orb (six glass orbs; the first follows the accent). */
export function avatarTone(name: string) {
  let hash = 7;
  for (const char of name.trim().toLowerCase()) hash = (hash * 31 + char.codePointAt(0)!) >>> 0;
  return hash % 6;
}

function AvatarContent({ src, initials }: { src?: string; initials: string }) {
  const [failed, setFailed] = useState(false);
  return (
    <>
      <span aria-hidden="true">{initials}</span>
      {src && !failed && (
        <img
          src={src}
          alt=""
          aria-hidden="true"
          width={32}
          height={32}
          decoding="async"
          className="absolute inset-0 size-full object-cover"
          ref={(image) => {
            // A cached or pre-hydration failure may precede the error listener.
            if (image?.complete && image.naturalWidth === 0) setFailed(true);
          }}
          onError={() => setFailed(true)}
        />
      )}
    </>
  );
}

export function Avatar({
  name,
  src,
  alt = name,
  presence,
  className,
  ...props
}: AvatarProps) {
  const words = name.trim().normalize("NFC").split(/\s+/u);
  const initials =
    (Array.from(words[0] ?? "")[0] ?? "?") +
    (words.length > 1 ? (Array.from(words[words.length - 1]!)[0] ?? "") : "");

  return (
    <span
      data-slot="avatar"
      data-tone={avatarTone(name)}
      className={cn(
        "relative inline-flex size-8 shrink-0 items-center justify-center rounded-full text-xs font-semibold",
        className,
      )}
      {...props}
      role={alt ? "img" : undefined}
      aria-label={alt || undefined}
      aria-hidden={!alt || undefined}
    >
      <AvatarContent
        key={src ?? ""}
        src={src}
        initials={initials.toUpperCase()}
      />
      {presence && <span data-slot="avatar-presence" data-presence={presence} aria-hidden="true" />}
    </span>
  );
}

import { Avatar } from "./avatar";
import { cn } from "./lib/cn";
import "./avatar-group.css";

export type AvatarGroupMember = {
  name: string;
  src?: string;
  status?: "online" | "offline";
};

export function AvatarGroup({
  members,
  max = 4,
  label = "Team members",
  className,
}: {
  members: readonly AvatarGroupMember[];
  max?: number;
  label?: string;
  className?: string;
}) {
  const shown = members.slice(0, Math.max(1, max));
  const extra = Math.max(0, members.length - shown.length);
  return (
    <div role="group" aria-label={label} data-slot="avatar-group" className={cn("inline-flex items-center", className)}>
      {shown.map((member) => (
        <span key={member.name} data-slot="avatar-group-item" className="relative">
          <Avatar name={member.name} src={member.src} className="ring-2 ring-background" />
          {member.status === "online" && (
            <span aria-hidden="true" data-slot="avatar-status" className="absolute right-0 bottom-0 size-2 rounded-full bg-success ring-2 ring-background" />
          )}
        </span>
      ))}
      {extra > 0 && (
        <span role="img" aria-label={`${extra} more`} data-slot="avatar-overflow" className="relative z-10 -ms-2 inline-flex size-8 items-center justify-center rounded-surface bg-muted text-xs font-medium ring-2 ring-background">
          +{extra}
        </span>
      )}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* avatar.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Avatars: a glass orb in the accent's own hue family. --accent is a fill that carries white at 4.5:1, so every tone
     stays at that depth and the initials are white; one accent pick recolours every orb. */
  [data-slot="avatar"] {
    --av-a: var(--accent);
    --av-b: color-mix(in srgb, var(--accent) 80%, #000);
    color: #fff;
    background:
      radial-gradient(circle at 32% 26%, rgb(255 255 255 / 40%), rgb(255 255 255 / 0%) 30%),
      radial-gradient(circle at 74% 80%, color-mix(in srgb, var(--av-b) 80%, #000), transparent 58%),
      linear-gradient(135deg, var(--av-a), var(--av-b));
    box-shadow: inset 0 0 0 1px rgb(255 255 255 / 14%), inset 0 -5px 10px rgb(0 0 0 / 14%);
  }
  [data-slot="avatar"] > span:first-child {
    position: relative;
    text-shadow: 0 1px 1px rgb(0 0 0 / 28%);
  }
  [data-slot="avatar"] img {
    border-radius: inherit;
  }
  [data-slot="avatar"][data-tone="1"] { --av-a: color-mix(in srgb, var(--accent) 88%, #000); --av-b: var(--accent); }
  [data-slot="avatar"][data-tone="2"] { --av-a: var(--accent); --av-b: color-mix(in srgb, var(--accent) 60%, #27272a); }
  [data-slot="avatar"][data-tone="3"] { --av-a: color-mix(in srgb, var(--accent) 75%, #52525b); --av-b: color-mix(in srgb, var(--accent) 85%, #000); }
  [data-slot="avatar"][data-tone="4"] { --av-a: color-mix(in srgb, var(--accent) 45%, #52525b); --av-b: color-mix(in srgb, var(--accent) 60%, #27272a); }
  [data-slot="avatar"][data-tone="5"] { --av-a: #6b6b73; --av-b: #3f3f46; }
  @supports (color: oklch(from red l c h)) {
    [data-slot="avatar"][data-tone="1"] { --av-a: oklch(from var(--accent) calc(l - 0.04) c calc(h + 24)); --av-b: oklch(from var(--accent) calc(l - 0.04) c calc(h + 48)); }
    [data-slot="avatar"][data-tone="2"] { --av-a: oklch(from var(--accent) calc(l - 0.04) c calc(h - 24)); --av-b: oklch(from var(--accent) calc(l - 0.04) c calc(h - 48)); }
    [data-slot="avatar"][data-tone="3"] { --av-a: oklch(from var(--accent) calc(l - 0.02) calc(c * 0.85) calc(h + 12)); --av-b: oklch(from var(--accent) calc(l - 0.06) calc(c * 0.7) calc(h - 12)); }
  }
  [data-slot="avatar-presence"] {
    position: absolute;
    right: -3px;
    bottom: -3px;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    box-shadow: 0 0 0 2px var(--background);
  }
  [data-slot="avatar-presence"][data-presence="online"] { background: var(--success); }
  [data-slot="avatar-presence"][data-presence="away"] { background: linear-gradient(90deg, var(--warning) 50%, var(--background) 50%); box-shadow: 0 0 0 2px var(--background), inset 0 0 0 1.5px var(--warning); }
  [data-slot="avatar-presence"][data-presence="busy"] { background: radial-gradient(var(--background) 0 0) center / 5px 1.5px no-repeat, var(--danger); }
  [data-slot="avatar-presence"][data-presence="offline"] { background: var(--background); box-shadow: 0 0 0 2px var(--background), inset 0 0 0 1.5px var(--muted-foreground); }
}

/* avatar-group.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="avatar-group-item"] {
    margin-inline-start: -0.5rem;
    transition: margin-inline-start var(--duration-fast) var(--ease-out);
  }
  [data-slot="avatar-group-item"]:first-child {
    margin-inline-start: 0;
  }
  @media (hover: hover) and (pointer: fine) {
    [data-slot="avatar-group"]:hover [data-slot="avatar-group-item"] {
      margin-inline-start: 0.25rem;
    }
    [data-slot="avatar-group"]:hover [data-slot="avatar-group-item"]:first-child {
      margin-inline-start: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="avatar-group-item"] {
      transition: margin-inline-start 120ms var(--ease-out);
    }
  }
}
